REPLACE INTO `iptv_catalog_snapshot` VALUES ('get_series','[{\"num\":1,\"name\":\"Fury (2024) TR\",\"series_id\":13652,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/fqt9boJafg7zMyxHdoNS6CmlHoM.jpg\",\"plot\":\"Babasının ölümünün intikamını almak isteyen genç bir kadın, Paris\'in yeraltı dünyasının ara bulucusu Fury\'nin ağına dolanır.\",\"cast\":\"\",\"director\":\"Jean-Yves Arnaud, Yoann Legave\",\"genre\":\"Aksiyon & Macera / Suç\",\"releaseDate\":\"2024-03-01\",\"release_date\":\"2024-03-01\",\"last_modified\":\"1773856531\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/lOM5ho8qmqQh0F6cn1DxGB61RvR.jpg\",\"https://image.tmdb.org/t/p/w1280/v4nOOvC9mwEmMuZArMY0yDKCsk9.jpg\",\"https://image.tmdb.org/t/p/w1280/f2mXMBskmvzNnUghAbNyM7GPZTw.jpg\",\"https://image.tmdb.org/t/p/w1280/wCrRHa6GNeqdS882fs3hrVupfE3.jpg\",\"https://image.tmdb.org/t/p/w1280/Gri8VUmLVb9hLx0TH720Scvum9.jpg\"],\"youtube_trailer\":\"b9K-nKECgxw\",\"tmdb\":\"212588\",\"episode_run_time\":\"0\",\"category_id\":\"832\",\"category_ids\":[832]},{\"num\":2,\"name\":\"Kalp Sancısı (2026) TR\",\"series_id\":14100,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/rGeWjJxZpFCftDDroRIa1BvYfqX.jpg\",\"plot\":\"\",\"cast\":\"Renata Vaca, Juan Pablo Fuentes, Iván Amozurrutia\",\"director\":\"\",\"genre\":\"Dram\",\"releaseDate\":\"2026-09-02\",\"release_date\":\"2026-09-02\",\"last_modified\":\"1788355859\",\"rating\":\"10\",\"rating_5based\":\"5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/avfnPYtyKXjgnhqtKAt1PZO2h5I.jpg\",\"https://image.tmdb.org/t/p/w1280/9pOEY61ahz73KajleGlY8mBEHtK.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"290234\",\"episode_run_time\":\"0\",\"category_id\":\"832\",\"category_ids\":[832]},{\"num\":3,\"name\":\"Tuzlu Kahve (2026) TR YERLI\",\"series_id\":14099,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/iXgalcTI4nBc4Dw0Ef4LevCz1Qp.jpg\",\"plot\":\"İstanbul’un köklü ve varlıklı ailelerinden birinin torunu olan Derin, hayatını belirli bir plana göre yaşamaya çalışan, evlenip yuva kurmayı en büyük hedefi haline getirmiş genç bir kadındır. Ancak uzun süredir devam eden ilişkisine rağmen bir türlü gerçekleşmeyen düğün hazırlıkları ve ailesinin bitmek bilmeyen beklentileri, onu her geçen gün daha fazla baskı altına almaktadır.\\r\\n\\r\\nDiğer tarafta ise yıllardır yurt dışında yaşayan Mehmet, ailevi sebeplerle Türkiye’ye döner. Başarılı, kendi ayakları üzerinde duran ve hayatını alıştığı düzende sürdürmek isteyen Mehmet’in dönüşü, ailesi için yeni umutların başlangıcı olur. Özellikle annesi, oğlunun artık ülkesine, ailesine ve kuracağı yeni hayata bağlanmasını istemektedir. Bunun için oğluna bir gelin adayı bile bulmuştur.\\r\\n\\r\\nBambaşka dünyalara ait gibi görünen Mehmet ve Derin’in yolları, ailelerin beklentileri, geçmişten gelen yükler, sırlar, yanlış anlaşılmalar ve sürpriz karşılaşmalar eşliğinde kesişmeye başlar.\",\"cast\":\"Nebahat Çehre, Eda Ece, Buğra Gülsoy, Binnur Kaya, Cengiz Bozkurt, Nevra Serezli, Settar Tanrıöğen, Şevval Sam\",\"director\":\"Aslı Zengin\",\"genre\":\"Aile / Komedi\",\"releaseDate\":\"2026-09-01\",\"release_date\":\"2026-09-01\",\"last_modified\":\"1788343656\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/b01pkRNXBBZQ5TZwdsPbThFjNdo.jpg\",\"https://image.tmdb.org/t/p/w1280/i2C7xDd2Kc22GvQtgnvsFSzxa4T.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"330784\",\"episode_run_time\":\"140\",\"category_id\":\"137\",\"category_ids\":[137]},{\"num\":4,\"name\":\"Korku Burnu (2026) TR DUBLAJ\",\"series_id\":14092,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/pkhR1xBgHPgxYMlSBZE903XbmE4.jpg\",\"plot\":\"Evli ve mutlu iki avukatın geçmişlerinden gelen azılı bir katil hapisten çıkınca hayatlarını altüst edecek bir fırtına yaklaşır.\",\"cast\":\"Amy Adams, Javier Bardem, Patrick Wilson, Joe Anders, Lily Collias, Malia Pyles, CCH Pounder\",\"director\":\"Nick Antosca\",\"genre\"