db.org/t/p/w1280/s5KaidPKwFkCM7BvZALVQ7yjbI4.jpg\",\"https://image.tmdb.org/t/p/w1280/v6f9FUDDQfGIv8MLRQwlL0zvRjI.jpg\",\"https://image.tmdb.org/t/p/w1280/aYUF2DvPJg1YeMkNADWlnKz09FL.jpg\",\"https://image.tmdb.org/t/p/w1280/v360NtAKZ5shJqJzjEoRkmA4x2o.jpg\",\"https://image.tmdb.org/t/p/w1280/qpPlEMFmtXtQOsOldyFZiGHKCVq.jpg\"],\"youtube_trailer\":\"lV6sJlBbhPs\",\"tmdb\":\"203857\",\"episode_run_time\":\"0\",\"category_id\":\"832\",\"category_ids\":[832]},{\"num\":361,\"name\":\"To Cook a Bear (2025) TR 4K HDR\",\"series_id\":13163,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/ovUPzm0pE4W7iXQIvI87VwOWJzG.jpg\",\"plot\":\"1852\'nin Kuzey İsveç\'inde, bir papaz ve ailesi, düzensizliklerle dolu bir köy olan Kengis\'e gelir. Papaz toplumu iyileştirmek istemektedir ama köylülerin çoğu değişime karşıdır. Bir dizi tüyler ürpertici cinayet işlendiğinde, Papaz ve Sami üvey oğlu Jussi olayı araştırır, ancak köydeki yöneticiler tarafından engellenir. Gerilim tırmanır, sadakat sınanır ve Papaz bir yandan ailesini korumak, bir yandan da durmak bilmeyen bir katilin peşine düşmek zorunda kalır.\",\"cast\":\"Gustaf Skarsgard, Jonas Karlsson, Pernilla August, Ane Dahl Torp, Magnus Krepper, Sigrid Johnson, Tobias Zilliacus, Simon J. Berger\",\"director\":\"\",\"genre\":\"Suç / Dram / Gizem\",\"releaseDate\":\"2025-10-15\",\"release_date\":\"2025-10-15\",\"last_modified\":\"1760621115\",\"rating\":\"10\",\"rating_5based\":\"5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/aQiLb3L29b7qnnHyZ8EqM6hQzp6.jpg\",\"https://image.tmdb.org/t/p/w1280/jgu0G2VjKYeoEvEyu1DODQ00PuT.jpg\",\"https://image.tmdb.org/t/p/w1280/59T4uXVzG7nhS91haplDWeHKc8m.jpg\",\"https://image.tmdb.org/t/p/w1280/qXMplpyiOkRZxmcXCh8fCNLtCRK.jpg\",\"https://image.tmdb.org/t/p/w1280/ku4T1pwCEJhAds86QkChll6gXfP.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"281555\",\"episode_run_time\":\"0\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":362,\"name\":\"To Cook a Bear (2025) TR\",\"series_id\":1316