_id\":\"832\",\"category_ids\":[832]},{\"num\":856,\"name\":\"Mr. Plankton (2024) TR\",\"series_id\":11687,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6laAGCSuPnYbCnsAjhFiAqlDr1Z.jpg\",\"plot\":\"Talihsizliklerden nasibini almış bir adam ve son derece şanssız bir gelin adayı olan eski sevgilisi, adamın hayatının son yolculuğunda birbirlerine eşlik etmek zorunda kalırlar.\",\"cast\":\"우도환, 이유미, 오정세, 김해숙, 김민석, 이엘, 이해영, 오대환\",\"director\":\"홍종찬, 조용\",\"genre\":\"Komedi\",\"releaseDate\":\"2024-11-08\",\"release_date\":\"2024-11-08\",\"last_modified\":\"1731144689\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/7LmwKWqnd0sYLQvz0VvjdW5J8sN.jpg\",\"https://image.tmdb.org/t/p/w1280/l2r5a9rdwPVUDhKf77fRxrxVOfb.jpg\",\"https://image.tmdb.org/t/p/w1280/aKuLHKgSxsHyIstierMX56Puchl.jpg\",\"https://image.tmdb.org/t/p/w1280/be7mmTtLT5GeUUNeT75VYSyyN1l.jpg\"],\"youtube_trailer\":\"mt4wezFpLvA\",\"tmdb\":\"230448\",\"episode_run_time\":\"0\",\"category_id\":\"832\",\"category_ids\":[832]},{\"num\":857,\"name\":\"Uzaylı Araştırması (2024) TR\",\"series_id\":11686,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/t2dShYTM1heqVXv4Pjk3mbBqFy2.jpg\",\"plot\":\"Bu sürükleyici belgesel dizisinde efsanevi gazeteci George Knapp, UFO\'lar hakkında yeni kanıtlar ortaya çıkarmak ve gezegendeki varlıklarını araştırmak için dünyayı dolaşıyor.\",\"cast\":\"George Knapp\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2024-11-08\",\"release_date\":\"2024-11-08\",\"last_modified\":\"1731144681\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/ea7DLoGRwqQ3W2WKgDxnyPqMhAM.jpg\",\"https://image.tmdb.org/t/p/w1280/lJNuRUJQhflKS7JX0aQOZ2Q770Y.jpg\",\"https://image.tmdb.org/t/p/w1280/lscjUymZ6bhKeaL9yEcRSAsLHKu.jpg\"],\"youtube_trailer\":\"bUjTGsbb3C4\",\"tmdb\":\"274023\",\"episode_run_time\":\"0\",\"category_id\":\"832\",\"category_ids\":[832]},{\"num\":858,\"name\":\"