":[349]},{\"num\":1071,\"name\":\"Transformers: BotBots\",\"series_id\":9390,\"cover\":\"https://image.tmdb.org/t/p/w154/hKtDA3GG3puz5DGnieFCNRGPpjK.jpg\",\"plot\":\"\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Çocuklar / Animasyon\",\"releaseDate\":\"2022-03-25\",\"release_date\":\"2022-03-25\",\"last_modified\":\"1694290762\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[],\"youtube_trailer\":\"k6uAQNDSnQA\",\"tmdb\":\"125574\",\"episode_run_time\":\"25\",\"category_id\":\"349\",\"category_ids\":[349]},{\"num\":1072,\"name\":\"Transformers: EarthSpark | TR\",\"series_id\":9389,\"cover\":\"https://image.tmdb.org/t/p/w154/ceVun5ktxwbAQFliomMmzOl05S3.jpg\",\"plot\":\"\",\"cast\":\"Danny Pudi, Kathreen Khavari, Zeno Robinson, Sydney Mikayla, Zion Broadnax, Jon Jon Briones, Alan Tudyk, Rory McCann\",\"director\":\"Nicole Dubuc, Ant Ward, Dale Malinowski\",\"genre\":\"Animasyon / Çocuklar / Bilim Kurgu & Fantazi\",\"releaseDate\":\"2022-11-11\",\"release_date\":\"2022-11-11\",\"last_modified\":\"1694290707\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[],\"youtube_trailer\":\"iJk9BqQ45FU\",\"tmdb\":\"157747\",\"episode_run_time\":\"22\",\"category_id\":\"349\",\"category_ids\":[349]},{\"num\":1073,\"name\":\"Tom ve Jerry\",\"series_id\":9388,\"cover\":\"https://image.tmdb.org/t/p/w154/qO0aveHUNqKciN9hO5EvBQGtZ3d.jpg\",\"plot\":\"Tom ve Jerry, William Hanna ve Joseph Barbera tarafından yaratılmış kısa filmler serisi halinde, ev kedisi Tom (tam adı Thomas) ile onunla aynı mekanı paylaşan ev faresi Jerry arasında geçen şiddetli ve komik mücadeleleri anlatan animasyon serilerinin genel adıdır. İlk Tom ve Jerry animasyonu 1940 yılında yapılmıştır. Hanna ve Barbera ikilisi, Hollywood\'da bulunan MGM çizgi film stüdyosunda 1940 ile 1957 arasında 114 kısa film yazıp yönetmişlerdir. Bunlardan on üçü akademi ödülüne aday gösterildi, yedisi En İyi Kısa Animasyon Filmi Akademi Ödülü aldı.[1]\\r\\n\\r\\nMetro-Goldwyn-Mayer çizgi film stüdyosunun kapanmasından sonra, 1960 yılında Tom ve Jerry filmlerinin yapımcılığını Gene Deitch devraldı ve filmler Batı Avrupa\'da yapılmaya başlandı. 1963 yılında Tom ve Jerry, yapımcılığını Chuck Jones\'in almasıyla tekrar Hollywood\'a geldi. Kısa film serilerinin sonlandığı 1967 yılına gelindiğinde toplam 161 kısa film yapılmıştı.[1]\\r\\n\\r\\n1970\'li yıllara gelindiğine Hanna-Barbera birlikte bir film stüdyosu kurdular ve filmler televizyona taşındı. Seksenlerde ve Doksanlı yıllar boyunca çeşitli TV şovları gösterildi. Uzun filmler yapıldı ve özel şovlar yapıldı. Günümüzde ise Tom ve Jerry\'nin hakları Warner Bros. şirketine aittir ve 2006\'dan beri Tom and Jerry Tales adıyla yeni seriler yapılmakta ve ABD\'de çeşitli televizyon kanallarında gösterilmektedir.\",\"cast\":\"John Stephenson, Don Messick, Joe E. Ross\",\"director\":\"Joseph Barbera, William Hanna\",\"genre\":\"Animasyon / Komedi / Çocuklar / Aile\",\"releaseDate\":\"1975-09-06\",\"release_date\":\"1975-09-06\",\"last_modified\":\"1694290855\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"\",\"tmdb\":\"7842\",\"episode_run_time\":\"30\",\"category_id\":\"349\",\"category_ids\":[349]},{\"num\":1074,\"name\":\"The Unstoppable Yellow Yeti\",\"series_id\":9387,\"cover\":\"https://image.tmdb.org/t/p/w154/nC8vuBqxtCBXHNHgSePjJLNb9qm.jpg\",\"plot\":\"\",\"cast\":\"Nadine Marshall, Emma Ballantine, Caoimhe Judd, Rasmus Hardiker, Amy-Leigh Hickman, Paul Tylak, Christopher Ragland, Harriet Carmichael\",\"director\":\"Anttu Harlin, Joonas Utti\",\"genre\":\"Animasyon / Komedi\",\"releaseDate\":\"2022-05-09\",\"release_date\":\"2022-05-09\",\"last_modified\":\"1694290601\",\"rating\":\"3\",\"rating_5based\":\"1.5\",\"backdrop_path\":[],\"youtube_trailer\":\"\",\"tmdb\":\"156613\",\"episode_run_time\":\"11\",\"category_id\":\"349\",\"category_ids\":[349]},{\"num\":1075,\"name\":\"The Snoopy Show\",\"series_id\":9386,\"cover\":\"https://image.tmdb.org/t/p/w154/qgB5CZwqrnZ99f8NHUL7ogPrgi3.