gory_ids\":[744]},{\"num\":2058,\"name\":\"Love, Victor\",\"series_id\":9479,\"cover\":\"https://image.tmdb.org/t/p/w154/pcT1vivabBnBk0tZgVBO1I8aK75.jpg\",\"plot\":\"\",\"cast\":\"Michael Cimino, Rachel Hilson, Anthony Turpel, Bebe Wood, Mason Gooding, George Sear, Isabella Ferreira, Mateo Fernandez\",\"director\":\"Isaac Aptaker, Elizabeth Berger\",\"genre\":\"Komedi / Dram\",\"releaseDate\":\"2020-06-17\",\"release_date\":\"2020-06-17\",\"last_modified\":\"1694541277\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[],\"youtube_trailer\":\"bJBvXAUo2Ug\",\"tmdb\":\"97186\",\"episode_run_time\":\"30\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2059,\"name\":\"Mayaların Kayıp Hazineleri | TR\",\"series_id\":9478,\"cover\":\"https://image.tmdb.org/t/p/w154/4AIHkaa2XrNWvciPqwHKk7z3Yc3.jpg\",\"plot\":\"National Geographic Kaşifi Albert Lin, yeni bir yüksek teknoloji eseri hazine haritasının on binlerce antik kalıntıyı nasıl ortaya çıkardığını keşfetmek için Guatemala ormanına girer. Düzinelerce arkeolog, 1.500 yıl sonra ilk kez kayıp kalıntıları keşfetmek için bir keşif yolculuğuna çıkar. Buldukları şeyler, dünyanın en gizemli antik uygarlıklarından birinin tarihini yeniden yazar.\",\"cast\":\"Albert Yu-Min Lin\",\"director\":\"\",\"genre\":\"Belgesel / Gizem\",\"releaseDate\":\"2019-03-04\",\"release_date\":\"2019-03-04\",\"last_modified\":\"1694541205\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[],\"youtube_trailer\":\"QG5hKxf0Kc0\",\"tmdb\":\"89666\",\"episode_run_time\":\"43\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2060,\"name\":\"Mısır\'ın Kayıp Hazinelerinin Peşinde\",\"series_id\":9477,\"cover\":\"https://image.tmdb.org/t/p/w154/5uAB8aQHrO2MFf0fB14083A6Ex.jpg\",\"plot\":\"Bu sürükleyici ve aksiyon dolu programda, dünyanın en zengin antik arkeoloji kaynağı olan Mısır\'ın Kayıp Hazineleri\'ni ortaya çıkaran uluslararası Mısırbilimci ekipleri izliyoruz. Kazılar ve arkeolojinin ön saflarında yer alan ekiplere benzeri görülmemiş erişim sayesinde, hayatlarının keşfini yapmak için kavurucu sıcak ve elverişsiz araziyle savaşan bu modern zaman kaşiflerini takip ediyoruz.\\r\\n\\r\\nBu sürükleyici ve aksiyon dolu programda, dünyanın en zengin antik arkeoloji kaynağı olan Mısır\'ın Kayıp Hazineleri\'ni ortaya çıkaran uluslararası Mısırbilimci ekipleri izliyoruz. Kazılar ve arkeolojinin ön saflarında yer alan ekiplere benzeri görülmemiş erişim sayesinde, hayatlarının keşfini yapmak için kavurucu sıcak ve elverişsiz araziyle savaşan bu modern zaman kaşiflerini takip ediyoruz.\",\"cast\":\"Julian Barratt\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2019-07-07\",\"release_date\":\"2019-07-07\",\"last_modified\":\"1694541143\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[],\"youtube_trailer\":\"aA7i6ZaFWr0\",\"tmdb\":\"87994\",\"episode_run_time\":\"45\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2061,\"name\":\"Lookism\",\"series_id\":9469,\"cover\":\"https://image.tmdb.org/t/p/w154/pPMQ3lqLrQiCDGlGsbjQ2rc2ZWu.jpg\",\"plot\":\"Bir lise öğrencisi sabah uyandığında, artık yakışıklı bir yüze ve mükemmel bir vücuda sahip olduğunu görür.\\r\\n\\r\\nPopüler bir Kore webtoon’undan uyarlanan bu animasyon dizisi, “DOTA: Dragon\'s Blood” ve “The Witcher: Nightmare of the Wolf”un yapımcısı olan Studio Mir imzasını taşıyor.\",\"cast\":\"Shim Kyu-hyuck, Han Shin, Ryu Seung-gone, Jeong Jae-heon, Nam Doh-hyeong, Hwang Chang-yung, Sa Moon-young, Lee Kyung-tae\",\"director\":\"\",\"genre\":\"Komedi / Dram / Animasyon\",\"releaseDate\":\"2022-12-08\",\"release_date\":\"2022-12-08\",\"last_modified\":\"1694455347\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"LPgBQSya5rU\",\"tmdb\":\"210942\",\"episode_run_time\":\"0\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2062,\"name\":\"Loki | TR\",\"series_id\":9468,\"cover\":\"https://image.tmdb.org/t/p/w154/w3cF2E269oUQIFq4IhRQ5MfkwMY.jpg\",\"plot\":\"Ma