drop_path\":[],\"youtube_trailer\":\"0PYhQ_gpilY\",\"tmdb\":\"203741\",\"episode_run_time\":\"58\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2089,\"name\":\"Doogie Kamealoha, M.D.\",\"series_id\":9436,\"cover\":\"https://image.tmdb.org/t/p/w154/absPCYGghhFsgP6Cx79kgYeCfbY.jpg\",\"plot\":\"\",\"cast\":\"Peyton Elizabeth Lee, Emma Meisel, Matthew Sato, Wes Tian, Jeffrey Bowyer-Chapman, Mapuana Makia, Kathleen Rose Perkins, Jason Scott Lee\",\"director\":\"Kourtney Kang\",\"genre\":\"Dram / Aile / Komedi\",\"releaseDate\":\"2021-09-08\",\"release_date\":\"2021-09-08\",\"last_modified\":\"1694442587\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"GlYxLChVy_0\",\"tmdb\":\"130372\",\"episode_run_time\":\"0\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2090,\"name\":\"Dopesick\",\"series_id\":9435,\"cover\":\"https://image.tmdb.org/t/p/w154/qW8Gpddy29faTcD7VuyKjwLXbKU.jpg\",\"plot\":\"Dizi, izleyicileri Purdue Ecza adlı ilaç firmasının yönetim kurulu odalarından, sıkıntılı bir Virginia maden topluluğuna ve DEA\'nın (Uyuşturucu ile Mücadele İdaresi) koridorlarına kadar Amerika\'nın opioid bağımlılığıyla mücadelesinin merkez üssüne götürüyor.\",\"cast\":\"Michael Keaton, Peter Sarsgaard, Michael Stuhlbarg, Kaitlyn Dever, Will Poulter, Rosario Dawson, John Hoogenakker, Will Chase\",\"director\":\"Danny Strong\",\"genre\":\"Dram / Suç\",\"releaseDate\":\"2021-10-13\",\"release_date\":\"2021-10-13\",\"last_modified\":\"1694442539\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"EzrLrUG2QVk\",\"tmdb\":\"110695\",\"episode_run_time\":\"62\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2091,\"name\":\"Gummi Ayıcıklarının Sevmli ve Sihirli Maceralari\",\"series_id\":9434,\"cover\":\"https://image.tmdb.org/t/p/w154/mqbX2l5Te3yMdAjDxvs5kRk0bhN.jpg\",\"plot\":\"Devler ve büyücüler, devler ve ejderhalar ve hem iyi hem de kötü harika yaratıkların mistik bir diyarında yüksek macera için dünyanın en tatlı kahramanlarına katılın. Gruffi, Zummi, Cubbi, Grammi, Tummi, Sünni ve tüm efsanevi Gummilerle gülerken, oynarken, alçakça entrikaları bozarken ve doğru olan için savaşırken tanışın. 1990 Li Yiların Eski Klasik Cizgi Filmi Tatlı Ayıların Seruvenleri ve Shirli Iksirlerin Oyrenilme Cabalari ve Arkadaslariyla hep belalardan kurtulma yi basarmalari. Yasadığı Maceralarini Anlatiyor 90larda TRT 1 t tarafimca Turkce seslendirmeli yayinlanmisti ve tekrar butun bolumlerle verilmesi harika olur Cocukluk Anilarimiz yeniden canlanir ve Lutfen HD Kaliteli Olsun\",\"cast\":\"June Foray, Lorenzo Music, Katie Leigh, Jim Cummings, Noelle North, Michael Rye, Will Ryan, Corey Burton\",\"director\":\"Michael Eisner, Jymn Magon, Art Vitello\",\"genre\":\"Animasyon / Aile / Çocuklar\",\"releaseDate\":\"1985-09-14\",\"release_date\":\"1985-09-14\",\"last_modified\":\"1694442528\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[],\"youtube_trailer\":\"77wNujaN0x8\",\"tmdb\":\"1931\",\"episode_run_time\":\"22\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2092,\"name\":\"The Mandalorian | TR\",\"series_id\":9433,\"cover\":\"https://image.tmdb.org/t/p/w154/eU1i6eHXlzMOlEq0ku1Rzq7Y4wA.jpg\",\"plot\":\"İmparatorluk\'un çöküşünden sonra yalnız bir Mandalorian, öksüzü Grogu\'yla beraber kanunsuz galakside dikkatle yol alır.\",\"cast\":\"Pedro Pascal, Katee Sackhoff, Taika Waititi, Emily Swallow, Chris Bartlett\",\"director\":\"Jon Favreau\",\"genre\":\"Bilim Kurgu & Fantazi / Aksiyon & Macera / Dram\",\"releaseDate\":\"2019-11-12\",\"release_date\":\"2019-11-12\",\"last_modified\":\"1694443054\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"2RVnrBLOBcI\",\"tmdb\":\"82856\",\"episode_run_time\":\"0\",\"category_id\":\"744\",\"category_ids\":[744]},{\"num\":2093,\"name\":\"Dirt\",\"series_id\":9432,\"cover\":\"https://image.tmdb.org/t/p/w154/JZs8u8XfZJDjv72LUidoXdb9qz.jpg\",\"plot\":\"\",\"cast\":\"Courte