ds\":[464]},{\"num\":2342,\"name\":\"Eko Eko Eko (2023) TR\",\"series_id\":5746,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/1dMldtEmNEtltZEWEOcXFLx8Va5.jpg\",\"plot\":\"Eko Eko Eko belgeseli, modern kentli insanın gezegenin yaşadığı ekolojik çöküşe nasıl tepki verdiğini sorguluyor. Belgeselde Ceren Moray’ın canlandırdığı iki karakter, günlük hayatta hepimizin aklını kurcalayan ekolojik çıkmazlara yanıt arıyor. Alanında uzman 26 akademisyen mevcut ekonomik düzenin ekolojik anlamda sürdürülebilir olup olmadığını ortaya koyuyor.\",\"cast\":\"Ceren Moray\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2023-02-03\",\"release_date\":\"2023-02-03\",\"last_modified\":\"1736674996\",\"rating\":\"10\",\"rating_5based\":\"5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/zRf4GIkGa7DuY3XKruqSj2H3PYF.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"221127\",\"episode_run_time\":\"60\",\"category_id\":\"151\",\"category_ids\":[151]},{\"num\":2343,\"name\":\"Lost Treasures of Rome\",\"series_id\":5728,\"cover\":\"https://image.tmdb.org/t/p/w154/oU0U7zFf7zApuSKrO8ftUUQgUsf.jpg\",\"plot\":\"This new series follows International teams of archaeologists on the front line, as they embark on a season of excavations to unravel the secrets of life in the Roman Empire. Crawling beneath Pompeii, unearthing an enormous lost coliseum, and hauling a 2000 year old battleship ram from the depths of the ocean, they race to unlock the secrets of this ancient civilization.\",\"cast\":\"Julian Barratt\",\"director\":\"\",\"genre\":\"Documentary\",\"releaseDate\":\"2022-05-27\",\"release_date\":\"2022-05-27\",\"last_modified\":\"1674995087\",\"rating\":\"5\",\"rating_5based\":\"2.5\",\"backdrop_path\":[],\"youtube_trailer\":\"NkWlxUcy5Fs\",\"tmdb\":\"202359\",\"episode_run_time\":\"60\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2344,\"name\":\"Lost Treasures of Egypt\",\"series_id\":5727,\"cover\":\"https://image.tmdb.org/t/p/w154/kYxwqzhXhkPj7ZJD6F65bPqVQxp.jpg\",\"plot\":\"An immersive, action-packed and discovery-led series following International teams of Egyptologists as they unearth the world\'s richest seam of ancient archaeology - Egypt\'s Valley of the Kings.\",\"cast\":\"Julian Barratt\",\"director\":\"\",\"genre\":\"Documentary\",\"releaseDate\":\"2019-07-07\",\"release_date\":\"2019-07-07\",\"last_modified\":\"1674994904\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"aA7i6ZaFWr0\",\"tmdb\":\"87994\",\"episode_run_time\":\"45\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2345,\"name\":\"Lost Treasures of the Maya\",\"series_id\":5726,\"cover\":\"https://image.tmdb.org/t/p/w154/4AIHkaa2XrNWvciPqwHKk7z3Yc3.jpg\",\"plot\":\"A new \\\"treasure map\\\" of the Maya world is transforming what we thought we knew of one of the world most mysterious ancient civilizations.\",\"cast\":\"Albert Yu-Min Lin\",\"director\":\"\",\"genre\":\"Documentary\",\"releaseDate\":\"2019-03-04\",\"release_date\":\"2019-03-04\",\"last_modified\":\"1674994317\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[],\"youtube_trailer\":\"QG5hKxf0Kc0\",\"tmdb\":\"89666\",\"episode_run_time\":\"0\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2346,\"name\":\"Station 19 EU\",\"series_id\":5724,\"cover\":\"https://image.tmdb.org/t/p/w154/lcuCED5Ky2uM5VE6wILOwt5FEb0.jpg\",\"plot\":\"A group of heroic firefighters at Seattle Fire Station 19—from captain to newest recruit—risk their lives and hearts both in the line of duty and off the clock. These brave men and women are like family, literally and figuratively, and together they put their own lives in jeopardy as first responders to save the lives of others.\",\"cast\":\"Jaina Lee Ortiz, Jason George, Boris Kodjoe, Grey Damon, Barrett Doss, Jay Hayden, Okieriete Onaodowan, Danielle Savre\",\"director\":\"Stacy McKee\",\"genre\":\"Drama / Action & Adventure\",\"releaseDate\":\"2018-03-22\",\"release_date\":\"2018-03-22\",\"last_modified\":\"1674993699\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[],\"youtube_trailer\":\"_0iIg59vZD4\",\"tmdb\":\"76773\",\"episode_run_time\":\"43\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2347,\"name\":\"Monsters at Work EU\",\"series_id\":5719,\"cover\":\"https://image.tmdb.org/t/p/w154/2gxgwhcuSmI5xtexb0t9zGj43FS.jpg\",\"plot\":\"Ever since he was a kid, Tylor Tuskmon has dreamed of becoming a Scarer just like his idol James P. Sullivan, and now that dream is about to come true... or not. The day he arrives at Monsters Incorporated to begin his dream job as a Scarer, he learns that scaring is out and laughter is in! After being reassigned to the Monsters, Inc. Facilities Team, Tylor sets his sights on a new goal: figuring out how to be funny and becoming a Jokester.\",\"cast\":\"Ben Feldman, Mindy Kaling, Henry Winkler, Lucas Neff, Alanna Ubach, Billy Crystal, John Goodman\",\"director\":\"Roberts Gannaway\",\"genre\":\"Family / Comedy / Animation\",\"releaseDate\":\"2021-07-07\",\"release_date\":\"2021-07-07\",\"last_modified\":\"1674992297\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[],\"youtube_trailer\":\"ijsh5RVYnoY\",\"tmdb\":\"90461\",\"episode_run_time\":\"27\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2348,\"name\":\"Secrets of the Underground\",\"series_id\":5718,\"cover\":\"https://image.tmdb.org/t/p/w154/gglwuZMul9pVl6CjJx2M0HUz3Pv.jpg\",\"plot\":\"\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Gerçeklik\",\"releaseDate\":\"2017-02-14\",\"release_date\":\"2017-02-14\",\"last_modified\":\"1674992144\",\"rating\":\"4\",\"rating_5based\":\"2\",\"backdrop_path\":[],\"youtube_trailer\":\"XAmgg3FKYhc\",\"tmdb\":\"70258\",\"episode_run_time\":\"60\",\"category_id\":\"151\",\"category_ids\":[151]},{\"num\":2349,\"name\":\"MECH-X4 EU\",\"series_id\":5712,\"cover\":\"https://image.tmdb.org/t/p/w154/acHYpTfMVKHxpI91Y6qjR4w75VC.jpg\",\"plot\":\"Ryan Walker mysteriously awakens MECH-X