:[\"http://mxb001.black-pars.com:8080/images/series/backdrop_rlahR2Dn0eP2ZYDFcPCZdszc8IS.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"88682\",\"episode_run_time\":\"60\",\"category_id\":\"350\",\"category_ids\":[350]},{\"num\":2378,\"name\":\"The Hot Zone (2019)\",\"series_id\":4732,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/cModMFJPO0yzhMR8bUkSxAoPPR.jpg\",\"plot\":\"Die Miniserie „The Hot Zone“ zeichnet die realen Hintergründe und den Ausbruch des Ebola-Virus Ende der 1980er Jahre nach. Sie zeigt, wie das Ebola-Virus, das sehr wahrscheinlich in einem Regenwald in Zentralafrika entstand, 1989 zum ersten Mal in die USA kam. Damals wurde es in einem Wissenschaftslabor in Washington, D.C. bei Schimpansen nachgewiesen. Eine Heilung war in weiter Ferne. Julianna Margulies spielt Dr. Nancy Jaax, eine Tierärztin der U.S. Army. Gemeinsam mit einem geheimen SWAT-Team versucht sie unter höchster Lebensgefahr, eine Übertragung auf die Stadtbevölkerung zu verhindern. (Text: RD)\",\"cast\":\"Daniel Dae Kim, Tony Goldwyn, Dylan Baker, Ian Colletti, Vanessa Matsui, Carlos Gonzalez-Vio\",\"director\":\"James V. Hart, Jeff Vintar, Kelly Souders\",\"genre\":\"Drama\",\"releaseDate\":\"2019-05-27\",\"release_date\":\"2019-05-27\",\"last_modified\":\"1722521830\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/aECd6NGBy6CSQGYNmlfwGxBvlom.jpg\",\"https://image.tmdb.org/t/p/w1280/npCaBQi941PRhHlUEWPws4qi10U.jpg\",\"https://image.tmdb.org/t/p/w1280/ncmR55IBWAvX6VAHMCgoCB9e9Jg.jpg\",\"https://image.tmdb.org/t/p/w1280/hip8oxolFG23czJ1Pntzo4dioev.jpg\",\"https://image.tmdb.org/t/p/w1280/fuPPfFi2f16oXFyO2XtuCxkKpRe.jpg\"],\"youtube_trailer\":\"6YxNYnHTxAg\",\"tmdb\":\"86799\",\"episode_run_time\":\"50\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2379,\"name\":\"Olaganüstü Arabalar\",\"series_id\":4904,\"cover\":\"https://pbs.twimg.com/media/CeZvy_TWQAAEIar.jpg\",\"plot\":\"\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"\",\"release_date\":\"\",\"last_modified\":\"1664470992\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://pbs.twimg.com/media/CeZvy_TWQAAEIar.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"0\",\"episode_run_time\":\"0\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2380,\"name\":\"The Strain\",\"series_id\":4907,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/2BWErT9QcADpf2G4BZ769eSnFTP.jpg\",\"plot\":\"Guillermo del Toro ve Chuck Hogan\'ın birlikte kaleme aldıkları üçleme kitabından uyarlanacak olan The Strain, bir vampir draması ama diğerlerinden biraz farklı. New York\'a gizemli bir şekilde iniş yapan uçağın yolcularının öldüğünün anlaşılması üzerine Hastalık Kontrol Merkezi yetkilisi Ephraim Goodweather (House of Cards - Corey Stoll), yaşanan bu tuhaf olayın sebeplerini araştırmaya başlar. Öncelikle uçakta yer alan dört yolcunun hâlâ yaşadığını farkeden ekip, olayla ilgili tek iyi haberin bu olduğunu kısa sürede öğrenirler...\",\"cast\":\"Corey Stoll, Kevin Durand, Miguel Gomez, David Bradley, Jonathan Hyde\",\"director\":\"\",\"genre\":\"Bilim Kurgu & Fantazi, Dram, Gizem\",\"releaseDate\":\"2014-07-13\",\"release_date\":\"2014-07-13\",\"last_modified\":\"1664471684\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/4YnAZ1KO9goeS4c06VO7HXiO3oO.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"47640\",\"episode_run_time\":\"44\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2381,\"name\":\"The Mighty Ducks: Game Changers\",\"series_id\":4930,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/ohfKOxy4028jm2XQL7Wy6cVMKhm.jpg\",\"plot\":\"In present day Minnesota, the Mighty Ducks have evolved from scrappy underdogs to an ultra-competitive, powerhouse youth hockey team. After 12-year-old Evan is unceremoniously cut from the Ducks, he and his mom Alex set out to build their own ragtag team of misfits to challenge the cutthroat, win-at-all-costs culture of competitive youth sports.\",\"cast\":\"Lauren Graham, Josh Duhamel, Brady Noon, Maxwell Simkins, Swayam Bhatia\",\"director\":\"\",\"genre\":\"Family, Comedy\",\"releaseDate\":\"2021-03-26\",\"release_date\":\"2021-03-26\",\"last_modified\":\"1670402877\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/70Uz9U2CjDBOqW8nJn0b7ZedEob.jpg\"],\"youtube_trailer\":\"OD3UhmRy4lg\",\"tmdb\":\"114621\",\"episode_run_time\":\"35\",\"category_id\":\"464\",\"category_ids\":[464]},{\"num\":2382,\"name\":\"Hoffman Family Gold\",\"series_id\":4964,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6IqV2MQxc4YCBzCqfyNG3nuIVBy.jpg\",\"plot\":\"\",\"cast\":\"Hunter Hoffman, Andy Spinks, Randy Hubler, Nick Young, Dakota Spinks\",\"director\":\"\",\"genre\":\"Gerçeklik\",\"releaseDate\":\"2022-03-25\",\"release_date\":\"2022-03-25\",\"last_modified\":\"1664995052\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/7ffa8YoS01PioccdEq9HnLLD42z.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"195916\",\"episode_run_time\":\"48\",\"category_id\":\"151\",\"category_ids\":[151]},{\"num\":2383,\"name\":\"Sen Uyuyunca\",\"series_id\":4969,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/ojNUTqoPKIpIQyP5N3pWjwa9ruH.jpg\",\"plot\":\"Uyku, günlük rutinimizin en önemli ve çoğunlukla en ihmal ettiğimiz parçası. Ömrümüzden çalıyor gibi görünen, hayatımızın üçte birini kapsayan uyku süresince aslında ne yaptığımızı, vücudumuzda ve beynimizde neler olduğunu hiç düşündünüz mü? Uyku problemleri yaşayan ve çözüm bulmak için birçok yolu deneyimleyen Bahar ile bir serüvene çıkıyoruz ve alanında uzman isimler, uykunun öteki yüzünü anlatıyor.\",\"cast\":\"Prof. Dr. Yavuz Selvi, Ayşegül Çoruhlu, Prof. Dr. Zerrin Pelin, Doç. Dr. Erkan Saka, Dr. Öğr. Üyesi Başak Türküler\",\"director\":\"Çetin Kerem Akbaş\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-05-25\",\"release_date\":\"2022-05-25\"