db.org/t/p/w1280/4QjnrMROQ65CBHFXO39oRyaYfuq.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"125352\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2563,\"name\":\"İmkansızı Yaşayanlar\",\"series_id\":10219,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2\",\"plot\":\"Hem dibi hem zirveyi görmüş sporcular anlatıyor. İmkansızı yaşamak birbirinden taban tabana zıt iki kutupta gerçekleşebiliyor. Kimileri dibi gördükten sonra dönüşü imkansız denilen noktalardan ayağa kalkar, kimileri adım adım süren mücadelenin sonunda ulaşabilecekleri en üst noktaya çıkar. Bir de \'imkansızı yaşayanlar\' vardır ve onlar hayatlarında dibi ve zirveyi aynı anda görür! Sporcuların hikayeleri kendi ağızlarından İmkansızı Yaşayanlar\'da.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-05-07\",\"release_date\":\"2021-05-07\",\"last_modified\":\"1702848063\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/94TmHb1FWp8MvsUqKc7MOXbdnvY.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"126009\",\"episode_run_time\":\"11\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2564,\"name\":\"İstanbul Hesabı\",\"series_id\":10220,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/4LPzz8EfhTEKTZLUfLTHlTo9Ese.jpg\",\"plot\":\"Kısıtlı bütçeyle İstanbul’u dolu dolu yaşamak, gezmek, uygun bütçeyle lezzetli şeyler yiyip içmek mümkün mü? Ahmet Mümtaz Taylan, az bir bütçeyle hem İstanbul’un farklı bölgelerinin ünlü yemeklerini tadıyor, hem de yerel halkla oranın kültürü ve tarihi üzerine eğlenceli sohbetler ediyor.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2020-12-30\",\"release_date\":\"2020-12-30\",\"last_modified\":\"1702849271\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/nx0OADL1blILLkafAPfeRtcjdJH.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"115818\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2565,\"name\":\"Jülide Ateş ile 40\",\"series_id\":10222,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/nsobv9DKl4okwkF1ibPnJv2yJws.jpg\",\"plot\":\"Format aynı, sorular yine cesur ve zor ama ekran yeni. \'Julide Ateş ile 40\' şimdi GAİN\'de! Türkiye\'ye \'Hard Talk\' formatını tanıtan, cesur sorularıyla gündem yaratan programın ilk bölüm konuğu sevilen oyuncu Ahmet Mümtaz Taylan.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2021-04-08\",\"release_date\":\"2021-04-08\",\"last_modified\":\"1711792783\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/9Wy9xKRMIoSicQuDo7QCv1XxJeL.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"123717\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2566,\"name\":\"K-POP Türkiye\",\"series_id\":10223,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6uPup8G75ULDA3U9ZvfarYK82ac.jpg\",\"plot\":\"Güney Kore’de doğup tüm dünyayı etkisi altına alan K-Pop’la ilgili tüm merak edilenler bu belgeselde cevap buluyor. Mersin’den Bursa’ya Türkiye’den cover dans grupları, vokaller, hayranlar, eğitmenler anlatıyor; Kore kültürü üzerine çalışan akademisyenler geçmişten geleceğe genel çerçeveyi çiziyor. Bu kültürel akımın gençlerin hayatını nasıl değiştirdiği ilk kez mercek altına alınıyor.  goplay\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-02-05\",\"release_date\":\"2022-02-05\",\"last_modified\":\"1702850841\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/vfl1u7GsmpQgIfXaTDQnC1pZ1SV.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"157038\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2567,\"name\":\"Kahveye bekleriz\",\"series_id\":10224,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6aB3kRxyIrCoOnAP2ovoFGOwEGa.jpg\",\"plot\":\"\'Kahve?” deyince asla reddetmeyenler için \'Sinan Kunter’le Kahveye Bekleriz\'.\\n\\nBu içeriği Tchibo katkılarıyla izliyorsunuz.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2022-06-01\",\"release_date\":\"2022-06-01\",\"last_modified\":\"1702850851\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280\"],\"youtube_trailer\":\"\",\"tmdb\":\"207205\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2568,\"name\":\"Komplo 19\",\"series_id\":10225,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/o4psCaqbtfsB0iGZrm1k2atrJck.jpg\",\"plot\":\"Komplo-19 11 Eylül’de İkiz Kuleler’e giren uçak değil hologram mıydı? Ay’a gerçekten gidildi mi? Bill Gates aşılarla nüfusu azaltmayı planladı mı? Dünya Sağlık Örgütü, devletlere yön veren bir ağın parçası mı? Dünyayı beş büyük aile mi yönetiyor? Çamlıca Kulesi şırınga şeklinde mi inşa edildi? COVID-19 aslında tüm insanları enjeksiyon yoluyla dize getirmek için abartılan bir virüs mü? GAİN yeni belgeseli ‘Komplo-19’la özellikle pandemi döneminde altın çağını yaşayan komplo dünyasına dalıyor. Aşı karşıtları, bilim insanları, sosyal bilimciler, araştırmacılar modern çağın giderek büyüyen fenomenini tüm yönleriyle anlatıyor. GOPLAY\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-01-14\",\"release_date\":\"2022-01-14\",\"last_modified\":\"1702850853\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/4dTcelANX9USz8G43l90UfsCKs9.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"156028\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2569,\"name\":\"Man with a Plan\",\"series_id\":10226,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/fCJMHR0GmR4layd4KQXC1HUPMlf.jpg\",\"plot\":\"\",\"cast\":\"Matt LeBlanc, Liza Snyder, Stacy Keach, Matt Cook, Kali Rocha\",\"director\":\"\",\"genre\":\"Komedi\",\"releaseDate\":\"2016-10-24\",\"release_date\":\"2016-10-24\",\"last_modified\":\"1702850919\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/hxeevnOc0TL1QGpmWnWhTRGUXwC.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"67156\",\"episode_run_time\":\"22\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2570,\"name\":\"Mary Kills People\",\"series_id\":10227,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/4zOZzlSjHjUJgc2Gp20iFfpkRBV.jpg\",\"plot\":\"Eşinden ayrılmış bir anne olan Mary Harris, gündüzleri bir acil servis doktorudur. Geceleri ise eski bir plastik cerrah olan ortağıyla birlikte, ölüm döşeğindeki hastaların yardımına koşan bir ölüm meleği. Ölüm döşeğindeki bu insanlara, kendi şartlarında ve istedikleri gibi dünyaya veda edebilmeleri için farklı ama yasa dışı olan bir ölme imkanı sunarlar.\",\"cast\":\"Caroline Dhavernas, Richard Short, Katie Douglas\",\"director\":\"\",\"genre\":\"Dram\",\"releaseDate\":\"2017-01-25\",\"release_date\":\"2017-01-25\",\"last_modified\":\"1702852480\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/83oRTo6vDeLKfvkNTgSKxmju1MX.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"69480\",\"episode_run_time\":\"45\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2571,\"name\":\"Metot\",\"series_id\":10228,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/3mPrkTWDDINX8aO0OUxWaQ1llTK.jpg\",\"plot\":\"Bir iş görüşmesi. Dört aday. İşi kapmak için gizem dolu sınavlardan geçip bütün hünerlerini göstermek zorunda kalan adaylar, bir süre sonra bu acımasız metotun bir parçası haline gelir.\",\"cast\":\"Serkan Keskin, Mustafa Kirantepe, Sarp Aydınoğlu, Şebnem Hassanisoughi\",\"director\":\"Serkan Keskin\",\"genre\":\"Gizem, Dram\",\"releaseDate\":\"2021-04-07\",\"release_date\":\"2021-04-07\",\"last_modified\":\"1702852487\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/7fQF7bJ7w0wpAlbyXknIOS1c2Bw.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"122632\",\"episode_run_time\":\"30\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2572,\"name\":\"Mirgün Cabas ile Yeni Dünya\",\"series_id\":10229,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/4pBszToumOk4UtbSOkIU4vAgCk5.jpg\",\"plot\":\"Sürdürülebilirlik, yenilenebilir enerji, dijital dönüşüm... Gelecek hızla yaklaşırken geleceğin iş dünyasını da yeni kavramlar şekillendiriyor. Mirgün Cabas, Yeni Dünya’da iş dünyasının önde gelenleriyle geleceği konuşuyor.\\n\\nBu içeriği Sabancı Holding\'in katkılarıyla izliyorsunuz.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Talk, Gerçeklik\",\"releaseDate\":\"2022-05-30\",\"release_date\":\"2022-05-30\",\"last_modified\":\"1702852499\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/oLwosjMGcQvkbELBpYNXmRspDLk.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"208215\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2573,\"name\":\"Ne Yaşandı?\",\"series_id\":10230,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/fJhPCBgJJ90GuFmuTh6HifJaIb4.jpg\",\"plot\":\"Savaşların, akıllara kazınan olayların en yakın tanıkları olan kameramanlar, muhabirler, gazeteciler o esnada ne yaşandığını anlatıyor. Herkes kaçarken haber peşinde koşan, kimi zaman yaralanan ama asla vazgeçmeyen gazetecileri dinlerken, olayların tüm gerçekliği tüylerinizi diken diken edecek.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2022-05-04\",\"release_date\":\"2022-05-04\",\"last_modified\":\"1717653751\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/pgrZrF5G4XhKkW2EBsz3uj6KSK7.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"207211\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2574,\"name\":\"Orda Rahat Mısın?\",\"series_id\":10231,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/xZndM0OE9sbUMQdgjtJaxe1RgQb.jpg\",\"plot\":\"İki koltuk, bir konuk, etkileyici bir yaşam, bir yolculuk ve pek çok soru… Mirgün Cabas mesleklerinde zirveye çıkmış isimlerden şu anda bulundukları noktada kendilerini nasıl hissettiklerini öğrenmek için soruyor: Orda rahat mısın?\",\"cast\":\"Mirgün Cabas\",\"director\":\"Mirgün Cabas\",\"genre\":\"Gerçeklik\",\"releaseDate\":\"2021-11-05\",\"release_date\":\"2021-11-05\",\"last_modified\":\"1702854085\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/vxzd9QVVkpGBF4MjUuMoI9z5DqA.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"138464\",\"episode_run_time\":\"60\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2575,\"name\":\"Orta! Kafa! Aşk!\",\"series_id\":10232,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/iOPBgM8HzoQ8rTttPBtaA5DgP87.jpg\",\"plot\":\"Eğer hayatınızı iki spor yorumcusu takip edip, yorumlasaydı nasıl olurdu? Semih ve Selin\'in aşkları, kavgaları, heyecanları, kıskançlıkları iki spor yorumcusu Fikri ve Mesut\'un gözünden aktarılıyor. Taca çıkan muhabbetler, kıran kırana mücadeleler, maçı geri döndürme çabaları, ağır çekimde izlenen pozisyonlar. Semih ve Selin yorumcuları hiç görmeseler de biz her hafta onların dünyasına konuk oluyor, ünlü konukların da katılımıyla farklı müsabakalara tanık oluyoruz. goplay\",\"cast\":\"Cengiz Bozkurt, Engin Hepileri, Su Kutlu, Can Sipahi\",\"director\":\"Can Evrenol\",\"genre\":\"Komedi, Aile\",\"releaseDate\":\"2021-09-20\",\"release_date\":\"2021-09-20\",\"last_modified\":\"1702854114\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/6SWVWdW7Ca6K2he0q4A7L64k6ZU.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"134213\",\"episode_run_time\":\"25\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2576,\"name\":\"Oyunlar Holding\",\"series_id\":10233,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/y1L3pR2SXVXzzQvJpRv3UV3L2JO.jpg\",\"plot\":\"Podcast dünyasını sallayan, senelerce listelerde bir numara olan “O Tarz mı?” ve “Podcastia” yaratıcıları bilardodan Sims’e, kutu oyunlarından atari oyunlarına her türlü oyunu el emeği kostümleri ve DIY objelerle oynuyor.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Gerçeklik\",\"releaseDate\":\"2021-01-03\",\"release_date\":\"2021-01-03\",\"last_modified\":\"1702854166\",\"rating\":\"10\",\"rating_5based\":\"5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280\"],\"youtube_trailer\":\"\",\"tmdb\":\"115821\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2577,\"name\":\"Özelden Yürüyenler\",\"series_id\":10234,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/mDKwMNUdsZ289sQjsszgiQg3GcT.jpg\",\"plot\":\"Reklam ajansında çalışan Cem, ofise yeni gelen Sinem ile tanışır. Arkadaşları taktik verse de işler onun istediği gibi gitmez. Bu arada Sinem\'in mesaj grubunda ilk günkü dedikodular yapılır.\",\"cast\":\"Yiğit Kalkavan\",\"director\":\"\",\"genre\":\"Komedi, Gerçeklik\",\"releaseDate\":\"2021-01-02\",\"release_date\":\"2021-01-02\",\"last_modified\":\"1702854208\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280\"],\"youtube_trailer\":\"\",\"tmdb\":\"121168\",\"episode_run_time\":\"15\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2578,\"name\":\"Şaka Bi\' Yana\",\"series_id\":10238,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/1ujk6PrWj0Apc9bMyzQQr4pOCkn.jpg\",\"plot\":\"Hayattan kesitler anlatarak insanları güldüren stand-up’çılar, kendi hayatlarının gerçeklerini bu belgeselde ortaya döküyorlar. Stand-up’ın sırlarından bu işe nasıl başladıklarına, sahnede yaşadıkları anılardan kulis sohbetlerine, şakaları hazırlama süreçlerinden otosansüre kadar her konunun derinliklerine iniyoruz. Mesut Süre, Cem İşçiler, Cihan Talay, Baturay Özdemir, Buse Sinem İren, Aslı Akbay, Oktay Şenol ve Rüya Aslangül’ü takip ettiğimiz komik bir yolculuğa hazır mısınız?\",\"cast\":\"Baturay Özdemir, Aslı Akbay, Rüya Aslangül, Mesut Süre, Cem İşçiler\",\"director\":\"Sertaç Selvi, Murat Onur Öner\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-04-01\",\"release_date\":\"2022-04-01\",\"last_modified\":\"1702855720\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/zUZgU55MzGdAUxTpnfIPTpgRbho.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"196593\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2579,\"name\":\"Sakin\",\"series_id\":10239,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/68QyxDKrIPtUXu7mW8oaZV5lsMv.jpg\",\"plot\":\"Şef Pınar Taşdemir şehrin keşmekeşinden uzak, doğanın huzurunda yemek yapma deneyimini görsel ve işitsel bir meditasyon halinde, sessiz bir şekilde paylaşıyor. Sakinleşmek için sesi açın.\",\"cast\":\"Zeynep Pınar Taşdemir\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-02-14\",\"release_date\":\"2021-02-14\",\"last_modified\":\"1702855725\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/paVKf45Xp3Jw4s3T6lbHy8sH51M.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"123229\",\"episode_run_time\":\"35\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2580,\"name\":\"Şarkı Hikayeleri\",\"series_id\":10240,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/kH4NTc9Cby7x4RsFinMo07PM4CR.jpg\",\"plot\":\"Dinlerken “acaba bu şarkı nasıl yapıldı?” “kime yazıldı?” diye düşünmeden edemediğimiz şarkıların hikayelerini, bizzat şarkının yaratıcılarından dinliyoruz.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Gerçeklik\",\"releaseDate\":\"2021-11-12\",\"release_date\":\"2021-11-12\",\"last_modified\":\"1702855733\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/aiHmCQXI6gidxbtE1Ybq280V6hq.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"138439\",\"episode_run_time\":\"5\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2581,\"name\":\"Senkron\",\"series_id\":10241,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/ygDrW9pnA90CjdCuu0O4BAEfmtf.jpg\",\"plot\":\"Zaman, yaşadığımız dünya ve içinde bulunduğumuz evreni sorgulatan bir bilim-kurgu. Seçmediğimiz onca şey bir başka gerçeklikte yaşamaya devam ediyorsa? Aynı gün, aynı anda, üç farklı hikayede buluşan Sedat ve Mina, paralel evrenlerinde seçmedikleri bambaşka hayatlarıyla yüzleşirler.\",\"cast\":\"Özcan Deniz, Feyza Aktan, Zeynep Tuğçe Bayat, Orçun Oran, Cansel Elçin\",\"director\":\"Özcan Deniz\",\"genre\":\"Bilim Kurgu & Fantazi\",\"releaseDate\":\"2021-04-07\",\"release_date\":\"2021-04-07\",\"last_modified\":\"1702855742\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/f99P0yOG1camjDUi9prt1JSxXto.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"122630\",\"episode_run_time\":\"43\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2582,\"name\":\"Şokopop Portreler: Banu Alkan\",\"series_id\":10242,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/kGhxo72tNN8gNm6dR2ckxya6HsG.jpg\",\"plot\":\"Geçmişten bugüne kadar ilgi ve merak konusu olan Afrodit efsanesinin doğuşunu, şöhret yolculuğunun detaylarını ve yaşadığı hayatını Şokopop merceğine alıyoruz.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2021-03-28\",\"release_date\":\"2021-03-28\",\"last_modified\":\"1702889747\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/h994IzOXqX1cyxVtooYIoVhTGIN.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"123037\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2583,\"name\":\"Şokopop Portreler: Harika Avcı\",\"series_id\":10243,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/sVBQJFlKkitlzWFYvgvGC1mdUTC.jpg\",\"plot\":\"Şokopop\'un merceğinde, 80\'li ve 90\'lı yılların en çok konuşulan magazin figürlerinden Harika Avcı ve adım adım kariyer basamakları var. Magazin çukuruna batmaya hazır olun.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-12-17\",\"release_date\":\"2021-12-17\",\"last_modified\":\"1702855754\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/jGDdeOmEu64rIPLVpDd8cKq0Abh.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"153860\",\"episode_run_time\":\"35\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2584,\"name\":\"Şokopop Portreler: Hülya Avşar\",\"series_id\":10244,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/7eBXyPWD3gCZwRBX8PSXu4HWog9.jpg\",\"plot\":\"Şokopop bu seride Müslüm Gürses’e göre Türkiye’nin “number one”ı, Meral Akşener’e göre Türkiye’nin Madonna’sı ve kendisine göre Türkiye’nin en akıllı ve en güzel kadını olan Hülya Avşar’ın hipermedyatik hayatını ve ışıltılı kariyer yolculuğunu GAİN izleyenleri için mercek altına alıyor.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-10-22\",\"release_date\":\"2021-10-22\",\"last_modified\":\"1702855758\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/vGM2wXf8bgL4ex43wpRJg2Do3hE.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"137088\",\"episode_run_time\":\"45\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2585,\"name\":\"Şokopop: Yeşilçam 101\",\"series_id\":10245,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/uVf3jCMerWMCb2qizxsCYFS9ido.jpg\",\"plot\":\"Yeşilçam 101’e hoşgeldiniz! Şokopop Hafıza Kurtarma Timi, TRT4 Açıköğretim programlarından ilham alarak sizler için hızlandırılmış bir Yeşilçam müfredatı hazırladı. Uzaktan eğitim ile katılacağınız bu üç temel dersin ardından siz de Yeşilçam evreninde kendi filminizi çekmeye hazır olacaksınız. Tüylü kalemleriniz ve kokulu silgileriniz hazırsa dersimiz başlıyor...\",\"cast\":\"\",\"director\":\"Ekim Acun\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-05-02\",\"release_date\":\"2021-05-02\",\"last_modified\":\"1702855763\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/4JJPH2xBSLlvMTnLooTPrBQxT8P.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"124732\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2586,\"name\":\"Şokopop Portreler: Megastar Tarkan\",\"series_id\":10246,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/hDm8TjtJ5bCsy0YFNdxjbpIKaH2.jpg\",\"plot\":\"Ülke sınırlarında eşi benzeri olmayan bir başarı elde eden, pop müziğinin açık ara en iyi isimlerinden olan Tarkan\'ın şanslı ve başarı dolu çıkışını ve hayatı Şokopop merceğinden sizinle.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-04-29\",\"release_date\":\"2021-04-29\",\"last_modified\":\"1711792705\",\"rating\":\"5\",\"rating_5based\":\"2.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/tjAYWbZ9RVgonjfdqpdJVOLhTND.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"127538\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2587,\"name\":\"Şokopop Portreler: Zeki Müren\",\"series_id\":10247,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6f4fGxGI8kOcJZz3XEnpT3696fB.jpg\",\"plot\":\"Zamanının en büyük sahne yıldızı Zeki Müren, 1950\'li yıllarında başladığı kariyerine 1990\'lara kadar neredeyse kesintisiz olarak devam ettirdi. Zorlu kariyer yolculuğunun ve medyaya yansımayan yönlerinin anlatıldığı Şokopop belgesel serisi sizlerle!\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel, Gerçeklik\",\"releaseDate\":\"2021-03-01\",\"release_date\":\"2021-03-01\",\"last_modified\":\"1702855777\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/nVF05KC58Xh9FJyNFrliz9Bve9a.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"123036\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2588,\"name\":\"Teleskobuma Takılanlar\",\"series_id\":10248,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/l3AvQWfOyhldD7KZ7Qk5xJHTz7d.jpg\",\"plot\":\"Pandemide herkes kendi içine dönerken, bir çift göz dışarı, hatta uzaya bakmaya karar verdi ve kendine bir teleskop aldı. Ancak teleskop gökyüzündeki yıldızları izlemektense şehrin gizli yıldızlarına odaklanmayı tercih etti.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2021-09-17\",\"release_date\":\"2021-09-17\",\"last_modified\":\"1702855787\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/4EPD01H1qX2qPpttIXcYVuleFQg.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"139451\",\"episode_run_time\":\"3\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2589,\"name\":\"Terapist\",\"series_id\":10249,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/mDgfODbpD2Tzh8keCTSlWYkyzBU.jpg\",\"plot\":\"Kişilik bozuklukları ve psikotik hastalıklar konusunda uzman olan terapist Çetin Düztaş’ın hayatı, karısının öldürülmesiyle altüst olur. Katilin bıraktığı ipucunun peşinden giden Çetin, geçmişin bugüne düşen gölgesini ararken, daha önce hiç fark etmediği gerçeklerle yüzleşmek zorunda kalır.\",\"cast\":\"Muhammet Uzuner, Murat Kılıç, Zeynep Çamcı, Ilayda Alişan, Dolunay Soysert\",\"director\":\"Zeynep Dadak\",\"genre\":\"Dram, Gizem\",\"releaseDate\":\"2021-01-01\",\"release_date\":\"2021-01-01\",\"last_modified\":\"1702855797\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/2FhSFL8NHjJhWfEzTvmDZHC2stF.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"115815\",\"episode_run_time\":\"15\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2590,\"name\":\"Tuz Biber\",\"series_id\":10251,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/jfDYqND3xb0Uu2URknTahT9nvtR.jpg\",\"plot\":\"Birbirine hiç benzemeyen komedyenler, stand-up show’larıyla hayata ve olaylara bakış açılarını anlatıyor. Modunuz ne olursa olsun TuzBiber izlerken gülmemek çok zor.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Talk\",\"releaseDate\":\"2021-01-16\",\"release_date\":\"2021-01-16\",\"last_modified\":\"1702857394\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/kvXKliec0N94xcEb0QHgYzkIvAz.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"157300\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2591,\"name\":\"Vedat Milor İle En İyisi\",\"series_id\":10252,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/x0FTPIkPx8NMj9Cwpn00dTlFgPQ.jpg\",\"plot\":\"Sosyal medyada yaptığı anketlerle fenomene dönüşen ünlü gurme Vedat Milor’la eğlenceli bir program. Milor, karar vermesi zor sorularıyla hem sosyal medyanın hem konunun uzmanlarının görüşlerini dinleyip kendi kararını gastronomik gerekçelerle açıklayacak.\",\"cast\":\"Vedat Milor\",\"director\":\"\",\"genre\":\"Gerçeklik\",\"releaseDate\":\"2020-12-30\",\"release_date\":\"2020-12-30\",\"last_modified\":\"1702857504\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280\"],\"youtube_trailer\":\"\",\"tmdb\":\"115820\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2592,\"name\":\"Yaşıma Başıma Bakmadan\",\"series_id\":10253,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/bzEyOe5Wg7bCuFHGzGHZKRLDOT9.jpg\",\"plot\":\"Yaş ilerledikçe tutku biter mi? Bir spora, bir sanata veya bambaşka bir şeye kafayı takmak için illa \'genç\' olmak mı gerekir? Kürekle İtalya\'ya giden, her gün koşan, durmaksızın şarkı söyleyen kısacası yaşına başına bakmadan bildiği yolda yürüyen, 70 yaş üstü insanların hikayelerine kulak verin. GOPLAY\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-01-07\",\"release_date\":\"2022-01-07\",\"last_modified\":\"1702857520\",\"rating\":\"5\",\"rating_5based\":\"2.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/bCHpb9GpCOZplzV47USsuOPmCBQ.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"156274\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2593,\"name\":\"Yatırım Tavsiyesi Değildir\",\"series_id\":10254,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/8nRg5kWGPm9MnhRsUXY2CcjnRCg.jpg\",\"plot\":\"Pandemi, ekonomik kriz, enflasyon, işsizlik, kolay para, lüks yaşama zahmetsiz kavuşma hayali…\\n\\nKimileri bu yolda sıfırı tüketti, kimi şanslı yatırımcı da hayalini bile kuramayacağı bol sıfırlı rakamlarla hayatını değiştirdi. Onlar artık ya çalışmıyor, ya da daha çok çalışıyor.\\n\\nBorsa ve Kripto Para piyasaları ile ilgili merak ettiğiniz her şeyi bulacağınız bu eğlenceli belgesel, kesinlikle bir Yatırım Tavsiyesi Değildir\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-03-12\",\"release_date\":\"2022-03-12\",\"last_modified\":\"1702857526\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/bdFQoRoEawfgF4Ssypwn1edbl6O.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"194936\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2594,\"name\":\"Yeni Gurmeler\",\"series_id\":10255,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/mwKTlt0nOJNAWCNFA7wzakfMpIx.jpg\",\"plot\":\"Dünya mutfağının farklı lezzetlerini test edenler, bu kez çocuklar. Deneyimleri yok ama kimseden çekinceleri de yok. Beş küçük çocuk hiç denemedikleri yemeklerle tanışıyor. Japon, Hint, İspanyol mutfağı ya da Türk mutfağının çocukların pek bilmediği, özel lezzetleri... Her bölümde karşılarına gelen tabaklara şüpheyle yaklaşan, beğenmediklerini açık sözlülükle eleştiren çocuklar, zorlu sınavlarının sonunda yemekleri puanlıyor. Bu cesur yüreklerin komik tepkilerini kaçırmayın.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2021-05-23\",\"release_date\":\"2021-05-23\",\"last_modified\":\"1702857554\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/dquxrd8EpUwOZlLE6TeJadzjota.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"129138\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2595,\"name\":\"İdil Yazar ile Hızlı ve Lezzetli\",\"series_id\":10478,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/x1HAt2lPRRHjRCG9zOi4bwJvic3.jpg\",\"plot\":\"Ünlü şef İdil Yazar’la yepyeni yemek programı Hızlı ve Lezzetli başlıyor! İdil Yazar mutfağında bir çırpıda yapılabilecek, tarif istetecek yemekleri yapıyor. Siz tarifi alın, soranlara ister verin ister vermeyin.\",\"cast\":\"İdil Yazar\",\"director\":\"\",\"genre\":\"Talk\",\"releaseDate\":\"2023-01-19\",\"release_date\":\"2023-01-19\",\"last_modified\":\"1706463714\",\"rating\":\"0\",\"rating_5based\":\"0\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/c2gKOq2V8Js8qip2YqHoPAuUF7.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"244785\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2596,\"name\":\"Yoldan Gönüllü Çıktım\",\"series_id\":10515,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6l3CIeiFFgiSNw2aZ5OyGnLMtPz.jpg\",\"plot\":\"Ünlü fotoğrafçı Levent Özçelik, Volvo’ya atlıyor ve yoldan gönüllü olarak çıkıyor.\\r\\n\\r\\nDünyanın az bilinen doğal güzelliklerini keşfediyor. Fotoğraf karesi gibi manzaraları izlerken dünyada böyle yerlerin olduğuna inanmayacaksınız.\",\"cast\":\"Levent Özçelik\",\"director\":\"\",\"genre\":\"\",\"releaseDate\":\"2021-10-20\",\"release_date\":\"2021-10-20\",\"last_modified\":\"1711878788\",\"rating\":\"6\",\"rating_5based\":\"3\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/A4CnwIjCLumT5wt5EYZ3oAoVHb7.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"245513\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2597,\"name\":\"İstanbul\'a Sürgün\",\"series_id\":10969,\"cover\":\"https://m.media-amazon.com/images/M/MV5BYzA1NjM5ZWUtNGZlYS00YjgxLWJmZDgtODFmYWQ2YmIxNGNkXkEyXkFqcGdeQXVyMTI4NjQzODEw._V1_FMjpg_UX1000_.jpg\",\"plot\":\"Moskova\'dan kaçıp İstanbul\'a sığınan gazeteciler anlatıyor.\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-05-01\",\"release_date\":\"2022-05-01\",\"last_modified\":\"1716403416\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280\"],\"youtube_trailer\":\"pQsjjxuviKM\",\"tmdb\":\"201977\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2598,\"name\":\"Heykel Mi?\",\"series_id\":11119,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/ciiytLUM5jTR8efacBerUl7MUwu.jpg\",\"plot\":\"Aslı İnandık’ın ilk durağı Alibeyköy mısır heykeli. Ama heykeli hakkıyla incelemek için önce Arkeoloji Müzesi’nde derin bir araştırma yapıyor ve bir bilene, bir daha az bilene, bir de hiç bilmeyenlere soruyor: \'Alibeyköy mısırı sizce bir heykel mi?\'\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Belgesel\",\"releaseDate\":\"2022-05-26\",\"release_date\":\"2022-05-26\",\"last_modified\":\"1719838443\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/ba16nYZDLJKt67Qu8fbutDioDne.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"203751\",\"episode_run_time\":\"0\",\"category_id\":\"173\",\"category_ids\":[173]},{\"num\":2599,\"name\":\"Python Eğitim Temel Bilgiler (2024) TR\",\"series_id\":12501,\"cover\":\"https://www.datocms-assets.com/64859/1648556515-python-egitimi.jpg?auto=format&fit=max&w=1200\",\"plot\":\"\",\"cast\":\"\",\"director\":\"\",\"genre\":\"Eğitim\",\"releaseDate\":\"2024\",\"release_date\":\"2024\",\"last_modified\":\"1747855435\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[\"https://radikalyazilim.com/wp-content/uploads/2022/01/python.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"0\",\"episode_run_time\":\"0\",\"category_id\":\"844\",\"category_ids\":[844]},{\"num\":2600,\"name\":\"İshak Danış Hatim Seti\",\"series_id\":12214,\"cover\":\"https://www.haydinamaza.net/medias/article/big/8/ishak-danis-kuran-i-kerim-hatmi-serif.jpg\",\"plot\":\"\",\"