org/t/p/w1280/bamB26mEh8Z0CR2nKK6TIGSDWNY.jpg\",\"https://image.tmdb.org/t/p/w1280/mH8jyRBx9KUZR16Aije4Jadl19S.jpg\",\"https://image.tmdb.org/t/p/w1280/jiw8kRQCJ4Fhk2s9GcPm3sTVa1A.jpg\",\"https://image.tmdb.org/t/p/w1280/kxbgDdBk4ZzoFo08dzPkB1tQzK7.jpg\",\"https://image.tmdb.org/t/p/w1280/39DH8VaGI5E0gsu8uLJfPKNGvvk.jpg\"],\"youtube_trailer\":\"B4tmmzh2PfA\",\"tmdb\":\"256116\",\"episode_run_time\":\"45\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2706,\"name\":\"Citadel Honey Bunny (2024) 4K HDR\",\"series_id\":11823,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/lzZ9J2FOsaq1DCuD7k2f4ogbXdD.jpg\",\"plot\":\"Dublör Bunny, zordaki oyuncu Honey\'yi bir ek iş için tutunca riskli bir aksiyon, casusluk ve ihanet dünyasına dalınır. Yıllar sonra tehlikeli mazileri yakalarına yapıştığında, ayrı düşmüş ikili Honey ve Bunny\'nin bir araya gelip küçük kızları Nadia\'yı korumak için savaşması gerekir.\",\"cast\":\"సమంత రూత్ ప్రభు, वरुण धवन, Kay Kay Menon, Kashvi Majmundar, Simran, Saqib Saleem, Sikandar Kher, Shivankit Singh Parihar\",\"director\":\"Sita Menon\",\"genre\":\"Aksiyon & Macera / Dram / Bilim Kurgu & Fantazi\",\"releaseDate\":\"2024-11-06\",\"release_date\":\"2024-11-06\",\"last_modified\":\"1733047762\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/arE8c9sAsjimV3nMoZsYNt5aIZZ.jpg\",\"https://image.tmdb.org/t/p/w1280/tn0Rn7kKXB9DwH8smBwkl66pYaG.jpg\",\"https://image.tmdb.org/t/p/w1280/hf3mq5cfXTdKHiW3UkZwSxbkx1A.jpg\",\"https://image.tmdb.org/t/p/w1280/9vIdrBwhsUJKwY8byjLRYNlyORS.jpg\",\"https://image.tmdb.org/t/p/w1280/mBH8kwkfoVmTO71V07DOWBZIXg1.jpg\"],\"youtube_trailer\":\"LOJCCsBdtVs\",\"tmdb\":\"154084\",\"episode_run_time\":\"0\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2707,\"name\":\"Citadel: Diana (2024) 4K HDR\",\"series_id\":11822,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/3iYf2GHc2jA6eBH2gMXXVJIKGt0.jpg\",\"plot\":\"Milano, 2030. Diana Cavalieri, sekiz yıl önce Citadel\'i yok eden rakip teşkilat Manticore\'a sızmış, gizli örgüt Citadel\'e çalışan bir çifte ajandır. Düşman elinde mahsur kalan Diana\'nın teşkilattan ayrılma şansı vardır ama beklenmedik bir müttefike, Manticore İtalya\'nın varisi Edo Zani\'ye güvenmek konusunda karar vermesi gerekmektedir.\",\"cast\":\"Matilda De Angelis, Lorenzo Cervasio, Maurizio Lombardi, Julia Piaton, Thekla Reuten, Giordana Faggiano, Daniele Paoloni, Jun Ichikawa\",\"director\":\"Alessandro Fabbri\",\"genre\":\"Aksiyon & Macera / Dram\",\"releaseDate\":\"2024-10-10\",\"release_date\":\"2024-10-10\",\"last_modified\":\"1733047650\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/jmJroNLm1PFfEImIYU77RJIuTPr.jpg\",\"https://image.tmdb.org/t/p/w1280/xsKGPcEnwTPI2CS3OrBVIEUzi1E.jpg\",\"https://image.tmdb.org/t/p/w1280/oKDA5vAw7sDMGO7GHVAivmRCBlN.jpg\",\"https://image.tmdb.org/t/p/w1280/bP7pC1fTXUiCb8pmAlCnM9ZcycS.jpg\",\"https://image.tmdb.org/t/p/w1280/hyfFQkZFyvfQXLQqt2rsUFzmTIg.jpg\"],\"youtube_trailer\":\"-EOOibYxoeQ\",\"tmdb\":\"214032\",\"episode_run_time\":\"0\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2708,\"name\":\"Homeland (2011) TR\",\"series_id\":11750,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6GAvS2e6VIRsms9FpVt33PsCoEW.jpg\",\"plot\":\"Irak\'ta öldürüldüğü tahmin edilen bir Amerikan askeri, kaybolduktan 8 yıl sonra geri döner. Ancak eve dönüş sevinci sona erdikten sonra, onun gerçekten bir Amerikan kahramanı olup olmadığı ya da bir terör saldırısı planlayan uyuyan bir hücrenin parçası olup olmadığı konusunda şüpheler ortaya çıkar.\",\"cast\":\"Claire Danes, Mandy Patinkin, Maury Sterling, Numan Acar, Nimrat Kaur, Linus Roache, Costa Ronin\",\"director\":\"Gideon Raff, Howard Gordon, Alex Gansa\",\"genre\":\"Dram / Savaş & Politik / Suç\",\"releaseDate\":\"2011-10-02\",\"release_date\":\"2011-10-02\",\"last_modified\":\"1732438920\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/zi40ANCqdvVqCN3q43g1hjdVCsp.jpg\",\"https://image.tmdb.org/t/p/w1280/391ixi0wVbFtFLQnOy8ZncWv2io.jpg\",\"https://image.tmdb.org/t/p/w1280/cN5EIn4vfkw7cccW5idaUQPNsKq.jpg\",\"https://image.tmdb.org/t/p/w1280/7xvIDNFVGOzj5uN3a5EoTADxjRr.jpg\",\"https://image.tmdb.org/t/p/w1280/8GXyKSYWvYF4qonFr93FWBJbAFy.jpg\"],\"youtube_trailer\":\"KyFmS3wRPCQ\",\"tmdb\":\"1407\",\"episode_run_time\":\"55\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2709,\"name\":\"Atatürk 1881-1919 (2024) TR YERLI\",\"series_id\":11697,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/1ycSNEDArSiapTHdiamVrYzQFt4.jpg\",\"plot\":\"Askeri okuldan vatansever bir idealist olarak mezun olan Kurmay Yüzbaşı Mustafa Kemal, 1919’a kadar Payitahta sadık bir asker olarak Osmanlı’nın her karışında savaşır. Bu süreçte, Osmanlı İmparatorluğu’nun aslında içten içe çürümeye başladığını anlar. Bir değişim gerektiği açıktır. Sürülür, açığa alınır, zorlanır, engellenir. Fakat hiçbir engel Mustafa Kemal\'in ilerleyişini durduramayacaktır.\",\"cast\":\"Aras Bulut İynemli, Songül Öden, Sarp Akkaya, Esra Bilgiç, Mehmet Günsür\",\"director\":\"\",\"genre\":\"Dram / Savaş & Politik / Belgesel\",\"releaseDate\":\"2024-11-10\",\"release_date\":\"2024-11-10\",\"last_modified\":\"1731328596\",\"rating\":\"10\",\"rating_5based\":\"5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/1IUMyNa4hp6bSmaNauAbtibC1o0.jpg\"],\"youtube_trailer\":\"\",\"tmdb\":\"276344\",\"episode_run_time\":\"0\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2710,\"name\":\"The Office(2005) TR\",\"series_id\":11260,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/7DJKHzAi83BmQrWLrYYOqcoKfhR.jpg\",\"plot\":\"Çalışanlarının mutluluğunu gözeterek şirket kurallarını esnetmeye çalışan, ara sıra masumane oyunların kurbanı, kaba ve taş kalpli bir şef: Michael Scott.\\r\\n\\r\\nHepsinin kendince takıntıları olan farklı yaş gruplarından personeliyle ile The Office çalışanlarının hayatlarına şöyle bir göz atıyor; bıkkın aynı zamanda yetenekli satış elemanı Jim, onun sosyopat, yalaka düşmanı Dwight, kibar ve dürüst resepsiyonisti Pam ve isteksiz, kayıtsız stajyeri Ryan.\",\"cast\":\"Rainn Wilson, John Krasinski, Jenna Fischer, Ed Helms\",\"director\":\"Greg Daniels\",\"genre\":\"Komedi\",\"releaseDate\":\"2005-03-24\",\"release_date\":\"2005-03-24\",\"last_modified\":\"1730732926\",\"rating\":\"9\",\"rating_5based\":\"4.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/b7wyaeJGU2Q4ql7xZr52vdW5TKp.jpg\",\"https://image.tmdb.org/t/p/w1280/gSX2JND7Ltb6LNfcBRE3SIrVO0v.jpg\",\"https://image.tmdb.org/t/p/w1280/mLyW3UTgi2lsMdtueYODcfAB9Ku.jpg\",\"https://image.tmdb.org/t/p/w1280/eDxBkRZRmbzwCxVqY1oSyTKNIid.jpg\",\"https://image.tmdb.org/t/p/w1280/eGfqlVKRhADPB0jqJxu74IWBTpW.jpg\"],\"youtube_trailer\":\"96ix3P9WaRc\",\"tmdb\":\"2316\",\"episode_run_time\":\"0\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2711,\"name\":\"Brooklyn Nine-Nine (2013) TR\",\"series_id\":11662,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/hgRMSOt7a1b8qyQR68vUixJPang.jpg\",\"plot\":\"Jake, işinde iyi, yetenekli ve ekibi içinde yakalama oranı en iyi polistir. Ama öteki yandan ciddiyetten yoksun ve sıkı çalışması gerekmemiş biri olarak oldukça da rahat biridir. Ekibe yeni gelen patron, emrindekilerin “rozetin hakkını vermesi” gerektiğini düşünen biri olarak işe koyulur ve Jake’ten başlar. Bu da komik pek çok olayın yaşanmasına sebebiyet verir. Brooklyn 99, New York’lu bir grup dedektifin ekip içi ve suçlularla yaşadığı komik olaylar üstüne kurulu olacak.\",\"cast\":\"Andy Samberg, Melissa Fumero, Terry Crews, Joe Lo Truglio, Stephanie Beatriz, Andre Braugher, Dirk Blocker, Joel McKinnon Miller\",\"director\":\"Michael Schur, Daniel J. Goor\",\"genre\":\"Komedi / Suç\",\"releaseDate\":\"2013-09-17\",\"release_date\":\"2013-09-17\",\"last_modified\":\"1730638072\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/9AeiA1XtP5sel2tAf9LaGeUjhDb.jpg\",\"https://image.tmdb.org/t/p/w1280/wyspZaGs7CXceV3Ct7NJhcKNDkn.jpg\",\"https://image.tmdb.org/t/p/w1280/lo6oxahzeFxDIYljDIAvK6GoibS.jpg\",\"https://image.tmdb.org/t/p/w1280/ncC9ZgZuKOdaVm7yXinUn26Qyok.jpg\",\"https://image.tmdb.org/t/p/w1280/jTiQAusGG4dVLSb1WHme9I9R4NN.jpg\"],\"youtube_trailer\":\"1GTVc1pLJKw\",\"tmdb\":\"48891\",\"episode_run_time\":\"21\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2712,\"name\":\"Parks and Recreation (2009) TR\",\"series_id\":11660,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/dDuzrl9rUIBYieZjqmtNCdncrmZ.jpg\",\"plot\":\"Amy Poehler, Pawnee, Indiana’nın Park ve Bahçeler Departmanı’ndaki orta kademe bir bürokrat olan Leslie Knope’u canlandırıyor. Kasabasını güzelleştirmeye -ve kariyerinde ilerlemeye- çalışan Leslie savunma halindeki bürokratlarla, huysuz komşularla ve hukuk davalarını silah olarak kullanan tek-sorun siyasetçileriyle, karmaşık il kodlarıyla ve çok sevdiği demokratik süreçlerle baş etmeye çalışıyor.\",\"cast\":\"Amy Poehler, Aziz Ansari, Nick Offerman, Aubrey Plaza, Chris Pratt, Adam Scott, Jim O\'Heir, Retta\",\"director\":\"Michael Schur, Greg Daniels\",\"genre\":\"Komedi\",\"releaseDate\":\"2009-04-09\",\"release_date\":\"2009-04-09\",\"last_modified\":\"1730637321\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/v7FPlZuuwJZ6YwJggf3Jx5pZNAz.jpg\",\"https://image.tmdb.org/t/p/w1280/frwl2zBNAl5ZbFDJGoJv0mYo0rF.jpg\",\"https://image.tmdb.org/t/p/w1280/4GdVgjpTGmmFEeDT2bXFPO1dbW9.jpg\",\"https://image.tmdb.org/t/p/w1280/rBLrpAVlv8G740xJaP3yqKNAtRK.jpg\",\"https://image.tmdb.org/t/p/w1280/eRjodgmrVNQQnIWJlzxPjd8PYkr.jpg\"],\"youtube_trailer\":\"5IZWeAwdJ-s\",\"tmdb\":\"8592\",\"episode_run_time\":\"22\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2713,\"name\":\"Battlestar Galactica (2004) TR\",\"series_id\":11659,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/99PJSbcO2LeM10uOGWeFihNp77j.jpg\",\"plot\":\"Miğferlerindeki bir sağa bir sola hareket eden ışıkla bilimkurgu tarihinin unutulmazları arasında yerini alan Saylonlar geri dönüyor. Üstelik kendilerini geliştirmiş olarak. Artık, insanlardan ayırt edilemeyen yepyeni modelleri de var. Ve bir kez daha uzayın uzak bir köşesindeki insan kolonilerini yıkıma uğratıyor, savaş yıldızı Galactica ve yanındaki irili ufaklı gemilerden oluşan filonun peşine düşüyorlar.\",\"cast\":\"Edward James Olmos, Mary McDonnell, Jamie Bamber, Katee Sackhoff, James Callis, Tricia Helfer, Tahmoh Penikett, Grace Park\",\"director\":\"Ronald D. Moore, Glen A. Larson\",\"genre\":\"Bilim Kurgu & Fantazi / Aksiyon & Macera / Dram\",\"releaseDate\":\"2004-10-18\",\"release_date\":\"2004-10-18\",\"last_modified\":\"1735655135\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/sEjNaoENrqIZONKNn1iLFB0Us9k.jpg\",\"https://image.tmdb.org/t/p/w1280/g9kImlLMC3AYwovHXHwPzie3msO.jpg\",\"https://image.tmdb.org/t/p/w1280/9EpgMSNwYBr7yI3C6FFJ2adR3Dh.jpg\",\"https://image.tmdb.org/t/p/w1280/9bSQNT7k3NQk16CYl4tTnhJOQGQ.jpg\",\"https://image.tmdb.org/t/p/w1280/80Ie9oz4PLoGLH6r9Q4jbKU1j3F.jpg\"],\"youtube_trailer\":\"s3E_PuRGCjc\",\"tmdb\":\"1972\",\"episode_run_time\":\"44\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2714,\"name\":\"Under the Dome (2013) TR\",\"series_id\":11464,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/fwH0ePhd7m3swtCuFeubtR49ZTd.jpg\",\"plot\":\"Görünmez ve gizemli bir güç alanı, Amerika\'nın Maine eyaletindeki Chester\'s Mill\'in küçük bir kasabasına inerek sakinleri medeniyetin geri kalanından kopararak içeride hapseder. Kapana kısılmış kasaba halkı, birbirleri ve hayvanlar hakkında bildiklerinden daha fazlasını öğrenirken, \\\"kubbe\\\" veya \\\"küre\\\" nin ve kökenlerinin sırlarını ve amacını keşfetmelidir.\",\"cast\":\"Mike Vogel, Rachelle Lefevre, Alexander Koch, Eddie Cahill, Colin Ford, Kylie Bunbury, Dean Norris, Mackenzie Lintz\",\"director\":\"Brian K. Vaughan\",\"genre\":\"Dram / Gizem / Bilim Kurgu & Fantazi\",\"releaseDate\":\"2013-06-24\",\"release_date\":\"2013-06-24\",\"last_modified\":\"1729028277\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/qiDOjpLj2KGDwM5MGx9YZpOrBRX.jpg\",\"https://image.tmdb.org/t/p/w1280/AvFsFV30q72B890gRqVRQ8YMYZm.jpg\",\"https://image.tmdb.org/t/p/w1280/lLoko1mWHeucujeVBRSxewKca97.jpg\",\"https://image.tmdb.org/t/p/w1280/mig8LxJN5q0ro7m4ogmPiV16Tqx.jpg\",\"https://image.tmdb.org/t/p/w1280/gzEoNlD7cKh5w3lPVJuGlR8PqBA.jpg\"],\"youtube_trailer\":\"RjyTkCCFeZU\",\"tmdb\":\"46331\",\"episode_run_time\":\"42\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2715,\"name\":\"Person of Interest (2011) TR\",\"series_id\":11410,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/6FuKOyJgViZXgMDOq9djFJLWPqX.jpg\",\"plot\":\"Kameralar her yerde! İzliyorlar, dinliyorlar, kaydediyorlar. Sizin hakkınızda her şeyi biliyorlar! Peki siz onlar hakkında ne biliyorsunuz? Gizemli bir iş adamı olan Mr. Finch, ileride işlenecek suçları önceden önlemeyi hedefleyen bir bilgisayar programı geliştirir. İlginç bir karaktere sahip bu milyoner işadamı elindeki programı hayata geçirebilmek için resmi kayıtlarda ölü olarak geçen Reese adlı eski bir CIA ajanıyla anlaşır. Kendi kaynakları ve teknolojisiyle Reese\'in yetenekleri ve sezgilerini birleştiren Mr. Finch\'in amacı gelecekte işlenecek olan suçları henüz suçlular eyleme geçmeden önlemektir.\",\"cast\":\"Jim Caviezel, Michael Emerson, Kevin Chapman, Amy Acker, Sarah Shahi\",\"director\":\"Jonathan Nolan\",\"genre\":\"Dram / Aksiyon & Macera / Suç / Bilim Kurgu & Fantazi\",\"releaseDate\":\"2011-09-22\",\"release_date\":\"2011-09-22\",\"last_modified\":\"1727988473\",\"rating\":\"8\",\"rating_5based\":\"4\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/hOdTVqJPXTnvmWeXgRZBlXDdoYE.jpg\",\"https://image.tmdb.org/t/p/w1280/ksmcQlCQc7XFGpXpIFZzF5twRSr.jpg\",\"https://image.tmdb.org/t/p/w1280/1fKMSDICRFotbAJ3ipgHr7rUbWN.jpg\",\"https://image.tmdb.org/t/p/w1280/3sCIyApg6jDoiTRwrNHHETRLQ8F.jpg\",\"https://image.tmdb.org/t/p/w1280/j4qTJxqRhpnV6dMcXss1Vnqn9fO.jpg\"],\"youtube_trailer\":\"_xAK3ueOJxE\",\"tmdb\":\"1411\",\"episode_run_time\":\"43\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2716,\"name\":\"Geçen Yaz Ne Yaptığını Biliyorum (2021) TR SUB.\",\"series_id\":11347,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/dJE2EwyFMn8iVP5IjIC6ShWkOUZ.jpg\",\"plot\":\"Dört arkadaş olan Ray, Barry, Helen ve Julie, başlarına geleceklerden bihaber okuldan mezun oldukları günü kutlar. Bir güzellik yarışmasına katılan ve kazanan Helen, birkaç ay içinde New York\'a gidip, filmlerde oynamayı planlar. Ray de New York\'a gidip ünlü bir yazar olmanın hayalini kurar. Barry ve Julie ise eğitimlerine ve hayatlarına Boston\'da devam edecektir. Ancak bunların hepsi sadece onların planıdır. Hayatın onlar için hazırladığı başka sürprizler vardır.\",\"cast\":\"Madison Iseman, Bill Heck, Brianne Tju, Ezekiel Goodman, Ashley Moore, Fiona Rene, Cassie Beck, Brooke Bloom\",\"director\":\"Sara Goodman\",\"genre\":\"Dram / Gizem\",\"releaseDate\":\"2021-10-14\",\"release_date\":\"2021-10-14\",\"last_modified\":\"1726691763\",\"rating\":\"7\",\"rating_5based\":\"3.5\",\"backdrop_path\":[\"https://image.tmdb.org/t/p/w1280/cENiQ3AJIHjpPsE9dW8KDmvldTK.jpg\",\"https://image.tmdb.org/t/p/w1280/TUksNV66TqJQUf2IUKAsuAdpUA.jpg\",\"https://image.tmdb.org/t/p/w1280/58tmwEO4mDRFiaVm62fZWFlKtpX.jpg\",\"https://image.tmdb.org/t/p/w1280/2I9uoNkxVZnsv5jYAUMV6ysHIGu.jpg\",\"https://image.tmdb.org/t/p/w1280/oyvgSKtnthgHUroYukuqLf4TJ9n.jpg\"],\"youtube_trailer\":\"IzL3ah9w98Y\",\"tmdb\":\"129680\",\"episode_run_time\":\"49\",\"category_id\":\"295\",\"category_ids\":[295]},{\"num\":2717,\"name\":\"Friends (1994) TR\",\"series_id\":11326,\"cover\":\"https://image.tmdb.org/t/p/w600_and_h900_bestv2/2koX1xLkpTQM4IZebYvKysFW1Nh.jpg\",\"